<?php
declare(strict_types=1);
namespace Nexus\Features\SolicitudRegistro\Infrastructure;
use Nexus\Features\SolicitudRegistro\Domain\SolicitudRegistroRepository;use Nexus\Shared\Domain\ValueObject\Cedula;
final class PdoSolicitudRegistroRepository implements SolicitudRegistroRepository
{
    private \PDO $pdo;public function __construct(\PDO $pdo){$this->pdo=$pdo;}
    public function listar():array{$q=$this->pdo->query('SELECT sr.id_solicitud_registro,sr.estado_solicitud,sr.id_usuario_manda,sr.id_usuario_responde,u.nombre,u.apellido,u.correo_electronico,u.rol,r.nombre responde_nombre,r.apellido responde_apellido FROM SOLICITUD_REGISTRO sr INNER JOIN USUARIO u ON u.cedula=sr.id_usuario_manda LEFT JOIN USUARIO r ON r.cedula=sr.id_usuario_responde ORDER BY sr.id_solicitud_registro DESC');return $q->fetchAll(\PDO::FETCH_ASSOC);}
    public function registroHabilitado():bool{$v=$this->pdo->query("SELECT valor FROM CONFIGURACION_SISTEMA WHERE clave='registro_habilitado'")->fetchColumn();return $v===false||$v==='1';}
    public function crearConUsuario(array $d):int{$this->pdo->beginTransaction();try{$q=$this->pdo->prepare("INSERT INTO USUARIO(cedula,nombre,apellido,correo_electronico,contrasena,estado,rol) VALUES(?,?,?,?,?,'Inactivo',?)");$q->execute([$d['cedula']->value(),$d['nombre'],$d['apellido'],$d['correo'],$d['hash'],$d['rol']]);$q=$this->pdo->prepare("INSERT INTO SOLICITUD_REGISTRO(estado_solicitud,id_usuario_manda) VALUES('Pendiente',?)");$q->execute([$d['cedula']->value()]);$id=(int)$this->pdo->lastInsertId();$this->pdo->commit();return $id;}catch(\Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}}
    public function resolver(int $id,string $estado,Cedula $admin):bool{$this->pdo->beginTransaction();try{$q=$this->pdo->prepare("SELECT id_usuario_manda FROM SOLICITUD_REGISTRO WHERE id_solicitud_registro=? AND estado_solicitud='Pendiente' FOR UPDATE");$q->execute([$id]);$cedula=$q->fetchColumn();if($cedula===false){$this->pdo->rollBack();return false;}$q=$this->pdo->prepare('UPDATE SOLICITUD_REGISTRO SET estado_solicitud=?,id_usuario_responde=? WHERE id_solicitud_registro=?');$q->execute([$estado,$admin->value(),$id]);if($estado==='Aprobado'){$q=$this->pdo->prepare("UPDATE USUARIO SET estado='Activo',rol=IF(rol='Administrador','Solicitante',rol) WHERE cedula=?");$q->execute([$cedula]);}$this->pdo->commit();return true;}catch(\Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}}
}
